const managedAccounts=[
  {id:'all',name:'全部账户',type:'汇总账户',currency:'人民币',description:'汇总两个实盘账户，统一折算为人民币',members:['cmb','global'],records:174,archived:false},
  {id:'cmb',name:'招商证券',type:'实盘账户',currency:'人民币',description:'A 股实盘账户 · 移动加权成本',broker:'招商证券',start:'2026/01/01',initial:'800000.00',commission:'2.5',minFee:'5.00',stamp:'5.0',records:126,archived:false},
  {id:'global',name:'港美股账户',type:'实盘账户',currency:'人民币',description:'港股、美股实盘账户 · 支持多币种',broker:'港美股券商',start:'2026/01/01',initial:'300000.00',commission:'3.0',minFee:'15.00',stamp:'5.0',records:48,archived:false},
  {id:'sim',name:'高股息模拟盘',type:'模拟盘',currency:'人民币',description:'高股息策略验证 · 独立统计',start:'2026/02/01',initial:'500000.00',fill:'录入时实时价格',records:32,archived:false},
  {id:'old',name:'旧券商账户',type:'实盘账户',currency:'人民币',description:'已迁移历史交易，不再使用',broker:'旧券商',start:'2024/01/01',initial:'200000.00',commission:'2.5',minFee:'5.00',stamp:'5.0',records:86,archived:true}
];
let selectedManagedAccountId='all';
pageNames['account-manager']='账户管理';
const accountManagerPage=document.createElement('section');accountManagerPage.className='page';accountManagerPage.id='page-account-manager';accountManagerPage.innerHTML=`
  <div class="page-heading"><div><h1>账户管理</h1><p>管理账户规则与成员关系，历史交易始终保留</p></div><div class="heading-actions"><button class="button ghost" id="account-manager-back"><i data-icon="arrow-right" style="transform:rotate(180deg)"></i>返回账户收益</button><button class="button primary" id="new-managed-account"><i data-icon="plus"></i>新建账户</button></div></div>
  <div class="account-manager-summary"><div><span>实盘账户</span><strong>2</strong><small>独立记账</small></div><div><span>汇总账户</span><strong>1</strong><small>不单独记账</small></div><div><span>模拟盘</span><strong>1</strong><small>独立统计</small></div><div><span>已归档</span><strong id="archived-account-count">1</strong><small>历史数据保留</small></div></div>
  <div class="account-manager-workspace"><aside class="account-manager-list"><div class="account-manager-list-head"><h2>我的账户</h2><span id="managed-account-total">4 个账户</span></div><div id="managed-account-list"></div></aside><div class="account-manager-detail" id="account-manager-detail"></div></div>`;
$('.main-content').appendChild(accountManagerPage);hydrateIcons(accountManagerPage);
function managedAccount(){return managedAccounts.find(account=>account.id===selectedManagedAccountId)}
function managedAccountIcon(account){return account.type==='汇总账户'?'全':account.type==='模拟盘'?'模':account.id==='global'?'港':'实'}
function renderManagedAccountList(){const active=managedAccounts.filter(account=>!account.archived),archived=managedAccounts.filter(account=>account.archived),groups=[['汇总账户','账户总览'],['实盘账户','实盘账户'],['模拟盘','模拟盘']];$('#managed-account-total').textContent=`${active.length} 个账户`;$('#archived-account-count').textContent=archived.length;$('#managed-account-list').innerHTML=groups.map(([type,label])=>{const accounts=active.filter(account=>account.type===type);if(!accounts.length)return'';return`<div class="account-list-section-label">${label}</div>${accounts.map(account=>`<button class="managed-account-item${account.id===selectedManagedAccountId?' active':''}" data-managed-account="${account.id}"><span class="account-icon ${account.type==='模拟盘'?'violet':account.id==='global'?'blue':'coral'}">${managedAccountIcon(account)}</span><span><strong>${account.name}</strong><small>${account.type} · ${account.currency}</small></span><b>${account.type==='汇总账户'?account.members.length+' 个成员':account.records+' 笔'}</b></button>`).join('')}`}).join('')+`<details class="account-restore-list"><summary class="account-list-section-label">已归档账户（${archived.length}）</summary>${archived.map(account=>`<button class="managed-account-item archived${account.id===selectedManagedAccountId?' active':''}" data-managed-account="${account.id}"><span class="account-icon">${managedAccountIcon(account)}</span><span><strong>${account.name}</strong><small>${account.type} · 已归档</small></span><b>${account.records} 笔</b></button>`).join('')}</details>`;$$('[data-managed-account]').forEach(btn=>btn.addEventListener('click',()=>{selectedManagedAccountId=btn.dataset.managedAccount;renderManagedAccountList();renderManagedAccountDetail()}))}
function managedAccountDetailHeader(account){return`<div class="account-detail-head"><div><span class="account-icon ${account.type==='模拟盘'?'violet':'coral'}">${managedAccountIcon(account)}</span><div><h2>${account.name}</h2><p>${account.type} · ${account.archived?'已归档，历史记录只读':'账户规则与记账设置'}</p></div></div><span class="soft-badge">${account.currency} 记账</span></div>`}
function renderManagedAccountDetail(){const account=managedAccount();if(!account)return;const detail=$('#account-manager-detail');let body=managedAccountDetailHeader(account);
  if(account.archived){body+=`<div class="account-form-section"><h3>账户已归档</h3><div class="description">该账户不再出现在默认统计中，${account.records} 笔历史记录全部保留。恢复后可继续编辑和记账。</div><div class="account-form-grid"><label>账户名称<input value="${account.name}" disabled/></label><label>记账币种<input value="${account.currency}" disabled/></label></div></div><div class="account-form-actions"><span>历史数据未删除</span><button class="button ghost" id="export-managed-records"><i data-icon="download"></i>导出历史记录</button><button class="button primary" id="restore-managed-account">恢复账户</button></div>`;detail.innerHTML=body;hydrateIcons(detail);$('#restore-managed-account',detail).addEventListener('click',()=>{account.archived=false;renderManagedAccountList();renderManagedAccountDetail();toast(`${account.name}已恢复`)});$('#export-managed-records',detail).addEventListener('click',()=>exportManagedRecords(account));return}
  body+=`<div class="account-form-section"><h3>基本信息</h3><div class="account-form-grid"><label>账户名称<input id="managed-account-name" value="${editorEscape(account.name)}"/></label><label>账户类型<select disabled><option>${account.type}</option></select></label><label>记账币种<select id="managed-account-currency"><option ${account.currency==='人民币'?'selected':''}>人民币</option><option ${account.currency==='美元'?'selected':''}>美元</option><option ${account.currency==='港币'?'selected':''}>港币</option></select></label><label>开始记账日期<input id="managed-account-start" value="${account.start||'2026/01/01'}"/></label><label class="full">账户说明<input id="managed-account-description" value="${editorEscape(account.description)}"/></label></div></div>`;
  if(account.type==='汇总账户')body+=`<div class="account-form-section"><h3>成员账户</h3><div class="description">汇总账户只合并所选实盘账户的持仓、现金和资金进出，本身不单独记账。模拟盘不会混入实盘汇总。</div>${managedAccounts.filter(item=>item.type==='实盘账户'&&!item.archived).map(member=>`<label class="account-member-row"><span>${member.name}<small>${member.currency} · ${member.records} 笔记录</small></span><input type="checkbox" data-managed-member="${member.id}" ${account.members.includes(member.id)?'checked':''}/></label>`).join('')}</div><div class="account-form-section"><h3>收益与折算</h3><div class="account-form-grid"><label>汇总展示币种<select><option>人民币</option></select></label><label>主收益率口径<select><option>时间加权收益率（份额净值法）</option></select></label></div></div>`;
  if(account.type==='实盘账户')body+=`<div class="account-form-section"><h3>默认交易费率</h3><div class="description">录入买卖时按此费率自动计算，仍可对每一笔费用手动修改。</div><table class="data-table"><thead><tr><th>费用项目</th><th class="num">费率（万分之）</th><th class="num">最低费用</th><th>收取方式</th></tr></thead><tbody><tr><td>佣金</td><td class="num"><input id="managed-commission" value="${account.commission}"/></td><td class="num"><input id="managed-min-fee" value="${account.minFee}"/></td><td>买卖双向</td></tr><tr><td>印花税</td><td class="num"><input id="managed-stamp" value="${account.stamp}"/></td><td class="num">无</td><td>卖出时收取</td></tr><tr><td>平台使用费</td><td class="num">0.00</td><td class="num">0.00</td><td>不收取</td></tr></tbody></table></div><div class="account-form-section"><h3>期初设置</h3><div class="account-form-grid"><label>期初资产（${account.currency}）<input value="${account.initial}"/></label><label>成本口径<select><option>移动加权平均</option><option>摊薄成本</option></select></label></div></div>`;
  if(account.type==='模拟盘')body+=`<div class="account-form-section"><h3>模拟盘设置</h3><div class="account-form-grid"><label>初始资金<input id="managed-sim-initial" value="${account.initial}"/></label><label>默认成交价格<select id="managed-sim-fill"><option ${account.fill==='录入时实时价格'?'selected':''}>录入时实时价格</option><option ${account.fill==='手动填写价格'?'selected':''}>手动填写价格</option></select></label><label>默认费用<select><option>不计费用</option><option>按实盘费率</option></select></label><label>统计方式<select><option>独立统计，不纳入实盘汇总</option></select></label></div></div>`;
  body+=`<div class="account-form-section"><h3>数据与记录</h3><div class="account-member-row"><span>交易与资金记录<small>${account.records} 笔 · 修改历史记录后自动重算收益</small></span><button class="button compact ghost" id="export-managed-records"><i data-icon="download"></i>导出 CSV</button><button class="button compact ghost" id="import-managed-records"><i data-icon="upload"></i>导入 CSV</button></div><div class="account-member-row"><span>同步状态<small>刚刚同步 · 本地与个人服务器各一份</small></span><span class="health-ok">正常</span></div></div><div class="account-form-section"><div class="account-danger-zone"><span><strong>归档此账户</strong><small>归档后不再默认显示，所有历史交易与收益记录保留，可随时恢复。</small></span><button class="button ghost danger" id="archive-managed-account">归档账户</button></div></div><div class="account-form-actions"><span>更改只影响后续记账，历史记录可重算</span><button class="button ghost" id="reset-managed-account">取消修改</button><button class="button primary" id="save-managed-account"><i data-icon="check"></i>保存设置</button></div>`;
  detail.innerHTML=body;hydrateIcons(detail);
  $('#reset-managed-account',detail).addEventListener('click',renderManagedAccountDetail);
  $('#save-managed-account',detail).addEventListener('click',()=>{const oldName=account.name,newName=$('#managed-account-name',detail).value.trim();if(!newName){toast('账户名称不能为空');return}account.name=newName;account.currency=$('#managed-account-currency',detail).value;account.description=$('#managed-account-description',detail).value;account.start=$('#managed-account-start',detail).value;if(account.type==='汇总账户')account.members=$$('[data-managed-member]:checked',detail).map(input=>input.dataset.managedMember);if(account.type==='实盘账户'){account.commission=$('#managed-commission',detail).value;account.minFee=$('#managed-min-fee',detail).value;account.stamp=$('#managed-stamp',detail).value}if(account.type==='模拟盘'){account.initial=$('#managed-sim-initial',detail).value;account.fill=$('#managed-sim-fill',detail).value}if(oldName!==newName){$$('.account-item strong').forEach(el=>{if(el.textContent===oldName)el.textContent=newName});if(accountVariants[oldName]){accountVariants[newName]=accountVariants[oldName];delete accountVariants[oldName]}}renderManagedAccountList();renderManagedAccountDetail();toast('账户设置已保存并同步')});
  $('#archive-managed-account',detail).addEventListener('click',()=>{account.archived=true;selectedManagedAccountId=managedAccounts.find(item=>!item.archived)?.id||account.id;renderManagedAccountList();renderManagedAccountDetail();toast(`${account.name}已归档，历史记录已保留`)});
  $$('#export-managed-records',detail).forEach(btn=>btn.addEventListener('click',()=>exportManagedRecords(account)));
  $('#import-managed-records',detail).addEventListener('click',()=>{const input=document.createElement('input');input.type='file';input.accept='.csv';input.addEventListener('change',async()=>{const file=input.files[0];if(!file)return;const text=await file.text(),count=Math.max(0,text.trim().split('\n').length-1);account.records+=count;renderManagedAccountList();renderManagedAccountDetail();toast(`已导入 ${count} 笔记录，收益已重新计算`)});input.click()});
}
function exportManagedRecords(account){downloadText(`${account.name}-交易记录.csv`,'\ufeff日期,账户,类型,股票,数量,成交价,费用\n2026/11/06,'+account.name+',买入,招商银行,1000,41.20,12.36\n2026/10/28,'+account.name+',卖出,中际旭创,200,276.40,18.62','text/csv;charset=utf-8');toast('账户交易记录已导出')}
function openAccountManager(id){if(id)selectedManagedAccountId=id;else{const current=$('.account-title h1')?.textContent;selectedManagedAccountId=managedAccounts.find(account=>account.name===current)?.id||'all'}switchPage('account-manager');$('.main-nav [data-page="accounts"]').classList.add('active');renderManagedAccountList();renderManagedAccountDetail()}
const manageAccountsButton=$('.account-list>.button.full');if(manageAccountsButton)rebind(manageAccountsButton,()=>openAccountManager());
$('#account-manager-back').addEventListener('click',()=>switchPage('accounts'));
$('#new-managed-account').addEventListener('click',()=>{let type='实盘账户';const modal=enhancedDialog('new-managed-account-dialog','新建账户','<div class="new-account-type-row"><button class="active" data-new-account-type="实盘账户">实盘账户</button><button data-new-account-type="模拟盘">模拟盘</button><button data-new-account-type="汇总账户">汇总账户</button></div><div class="account-form-grid"><label>账户名称<input id="new-account-name" placeholder="例如：长期实盘"/></label><label>记账币种<select id="new-account-currency"><option>人民币</option><option>美元</option><option>港币</option></select></label><label class="full">账户说明<input id="new-account-description" placeholder="可选"/></label><label id="new-account-initial-wrap" style="display:none">初始资金<input id="new-account-initial" value="500000.00"/></label></div><div id="new-account-members" style="display:none"><label class="account-member-row"><span>招商证券<small>实盘账户</small></span><input type="checkbox" value="cmb" checked/></label><label class="account-member-row"><span>港美股账户<small>实盘账户</small></span><input type="checkbox" value="global" checked/></label></div>',{actions:'<button class="button primary" id="create-managed-account">创建账户</button>'});$$('[data-new-account-type]',modal).forEach(btn=>btn.addEventListener('click',()=>{type=btn.dataset.newAccountType;$$('[data-new-account-type]',modal).forEach(el=>el.classList.toggle('active',el===btn));$('#new-account-initial-wrap',modal).style.display=type==='模拟盘'?'flex':'none';$('#new-account-members',modal).style.display=type==='汇总账户'?'block':'none'}));$('#create-managed-account',modal).addEventListener('click',()=>{const name=$('#new-account-name',modal).value.trim();if(!name){toast('请输入账户名称');return}const account={id:`account-${Date.now()}`,name,type,currency:$('#new-account-currency',modal).value,description:$('#new-account-description',modal).value||`${type} · 新建`,start:'2026/11/11',initial:$('#new-account-initial',modal).value,commission:'2.5',minFee:'5.00',stamp:'5.0',fill:'录入时实时价格',records:0,archived:false};if(type==='汇总账户')account.members=$$('#new-account-members input:checked',modal).map(input=>input.value);managedAccounts.push(account);selectedManagedAccountId=account.id;closeEnhancedDialog('new-managed-account-dialog');renderManagedAccountList();renderManagedAccountDetail();toast(`已创建${type}“${name}”`)})});
if(location.hash==='#account-manager')openAccountManager();
